"""Design.md behavior, responsive, accessibility and fallback integration checks."""
from pathlib import Path
from playwright.sync_api import sync_playwright
import json, os, hashlib

ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT/'docs/screenshots/design-final';OUT.mkdir(parents=True,exist_ok=True)
BASE=os.environ.get('PORTFOLIO_TEST_URL','http://localhost:4173').rstrip('/')
report={'checks':[],'failures':[],'errors':[],'http_failures':[]}
def check(name,value):
    (report['checks'] if value else report['failures']).append(name)
def shot(page,name):page.screenshot(path=str(OUT/(name+'.png')))
def instant(page,selector):page.locator(selector).evaluate('(e)=>scrollTo({top:scrollY+e.getBoundingClientRect().top-150,behavior:"instant"})')

with sync_playwright() as p:
    browser=p.chromium.launch(executable_path=os.environ.get('BROWSER_EXECUTABLE','C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe'),headless=True)
    ctx=browser.new_context(viewport={'width':1440,'height':1000})
    page=ctx.new_page();page.on('pageerror',lambda e:report['errors'].append(str(e)))
    page.on('response',lambda r:report['http_failures'].append({'status':r.status,'url':r.url}) if r.status>=400 else None)
    page.goto(BASE,wait_until='networkidle');page.wait_for_timeout(1500)
    check('one named h1',page.locator('h1').count()==1 and page.locator('h1').get_attribute('aria-label')=='Ratnadeep Patil')
    check('no project sequence labels',page.locator('.work-index .mono,.art-number').count()==0)
    check('primary CTA reaches demos',page.locator('.primary-cta').get_attribute('href')=='#work')
    shot(page,'hero')
    page.keyboard.press('Control+k');check('command palette opens',page.locator('.command-dialog').evaluate('(e)=>e.open'))
    check('command focus enters dialog',page.locator('.command-dialog').evaluate('(e)=>e.contains(document.activeElement)'))
    page.keyboard.press('Escape');check('Escape closes palette',not page.locator('.command-dialog').evaluate('(e)=>e.open'))
    instant(page,'#untangle');page.wait_for_function("document.querySelector('[data-knot]').dataset.renderer==='three'")
    check('signature lazy canvas mounts',page.locator('.knot-host canvas').count()==1)
    page.locator('#untangle').evaluate('(e)=>scrollTo({top:scrollY+e.getBoundingClientRect().top-80,behavior:"instant"})');page.wait_for_timeout(200)
    check('knot starts unmorphed',float(page.locator('[data-knot]').get_attribute('data-morph'))<.05)
    shot(page,'knot')
    page.locator('#untangle').evaluate('(e)=>scrollTo({top:scrollY+e.getBoundingClientRect().top+(e.offsetHeight-e.querySelector(".signature-stage").offsetHeight)-80,behavior:"instant"})');page.wait_for_timeout(200)
    check('scroll resolves into graph',float(page.locator('[data-knot]').get_attribute('data-morph'))>.95)
    check('four project nodes keyboard reachable',page.locator('.graph-project[tabindex="0"]').count()==4)
    shot(page,'graph')
    canvas=page.locator('.knot-host canvas');before=canvas.screenshot();page.wait_for_timeout(200);after=canvas.screenshot();check('3D actually renders moving frames',before!=after)
    page.locator('.signature-pause').click();page.wait_for_timeout(100);before=canvas.screenshot();page.wait_for_timeout(180);check('pause freezes rendered frame',before==canvas.screenshot())
    page.locator('.signature-pause').click()
    page.locator('[data-project-link="synora"]').click();page.wait_for_timeout(900)
    check('desktop reel enabled',page.locator('#work').evaluate('(e)=>e.classList.contains("reel-ready")'))
    page.locator('[data-memory="meeting"]').click();check('source connects',page.locator('[data-memory="meeting"]').get_attribute('aria-pressed')=='true')
    page.locator('[data-memory="document"]').click();check('source provenance remains attached','Meeting note' in page.locator('[data-memory-output]').inner_text() and 'Project document' in page.locator('[data-memory-output]').inner_text())
    page.locator('[data-memory-reset]').click();check('memory resets',page.locator('[data-memory][aria-pressed="true"]').count()==0)
    shot(page,'synora')
    page.locator('[data-project-link="contextguard"]').click();page.wait_for_timeout(900)
    page.locator('[data-compare]').click();check('conflict compare exposes clarification',page.locator('[data-clarify]').is_visible())
    page.locator('[data-clarify]').click();check('clarification produces brief',page.locator('[data-brief]').is_visible() and '19 November' in page.locator('[data-brief]').inner_text())
    check('original conflicting evidence retained',page.locator('.compare-docs mark').all_text_contents()==['12 November','19 November'])
    shot(page,'contextguard')
    page.locator('[data-gap-reset]').click();check('review reset restores open state',page.locator('[data-gap-state]').inner_text()=='Open question')
    page.locator('[data-project-link="termwise"]').click();page.wait_for_timeout(900)
    path=page.locator('[data-cash-line]').get_attribute('d')
    page.locator('[data-advance]').fill('70');page.wait_for_timeout(350);check('cash chart reshapes',page.locator('[data-cash-line]').get_attribute('d')!=path)
    check('70 percent requires no reserve',page.locator('[data-cash-reserve]').inner_text()=='$0')
    page.locator('[data-advance]').fill('10');page.wait_for_timeout(350);check('10 percent exposes 6000 reserve',page.locator('[data-cash-reserve]').inner_text()=='$6,000')
    page.locator('[data-advance]').focus();page.keyboard.press('ArrowRight');check('slider keyboard changes result',page.locator('[data-advance]').input_value()=='15')
    shot(page,'termwise')
    page.locator('[data-project-link="face-web-blockchain"]').click();page.wait_for_timeout(900)
    page.wait_for_function("document.querySelector('[data-hash-state]').textContent==='Integrity check passed'")
    original=page.locator('[data-hash-original]').inner_text();check('real 64-character SHA256',len(original)==64 and all(c in '0123456789abcdef' for c in original))
    check('displayed pixels match fingerprint',page.locator('.hash-sample svg').evaluate('async e=>{const bytes=new Uint8Array([...e.querySelectorAll("rect")].flatMap(r=>{const rgb=getComputedStyle(r).fill.match(/\d+/g).map(Number);return [...rgb,255]}));const hash=[...new Uint8Array(await crypto.subtle.digest("SHA-256",bytes))].map(b=>b.toString(16).padStart(2,"0")).join("");return hash===document.querySelector("[data-hash-original]").textContent}'))
    page.locator('[data-tamper]').click();page.wait_for_function("document.querySelector('[data-hash-state]').textContent==='Integrity check failed'")
    check('one pixel changes fingerprint',page.locator('[data-hash-current]').inner_text()!=original)
    shot(page,'integrity')
    page.locator('[data-hash-reset]').click();page.wait_for_function("document.querySelector('[data-hash-state]').textContent==='Integrity check passed'");check('restore reproduces original hash',page.locator('[data-hash-current]').inner_text()==original)
    # Native keyboard focus must scroll an offscreen reel panel into view.
    page.locator('[data-project-link="synora"]').click();page.wait_for_timeout(800)
    page.locator('[data-advance]').focus();page.wait_for_timeout(150);check('offscreen keyboard target becomes visible',page.locator('[data-advance]').bounding_box()['x']>=0 and page.locator('[data-advance]').bounding_box()['x']<1440)
    instant(page,'#skills');page.locator('[data-skill-projects="face-web-blockchain"]').click()
    check('Solidity maps to blockchain only',page.locator('[data-skill-result].is-match').count()==1 and page.locator('[data-skill-result="face-web-blockchain"]').evaluate('(e)=>e.classList.contains("is-match")'))
    check('matching skill connection highlights',page.locator('[data-skill-line].is-match').count()==1)
    shot(page,'skills')
    instant(page,'#about');page.wait_for_timeout(500)
    check('portrait self-hosted and loads',page.locator('.about-portrait').evaluate('(e)=>e.complete&&e.naturalWidth>0&&!e.src.includes("licdn")'))
    check('internship months come from CV','Nov 2025 - Jan 2026' in page.locator('.experience').inner_text() and 'Apr 2025 - Jul 2026' in page.locator('.experience').inner_text())
    shot(page,'about')
    page.evaluate("Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async v=>{window.__email=v}}})")
    page.locator('.copy-email').click();page.wait_for_timeout(80);check('copy microinteraction and email',' '.join(page.locator('.copy-email').inner_text().split())=='Copied ✓' and page.evaluate('window.__email')=='ratnadeepp2007@gmail.com')
    # All static routes, downloads and six widths.
    for route in ['/','/work/synora/','/work/contextguard/','/work/termwise/','/work/face-web-blockchain/']:
        page.goto(BASE+route,wait_until='networkidle')
        check('one heading '+route,page.locator('h1').count()==1)
        for width,height in [(320,740),(390,844),(768,1024),(1024,900),(1440,900),(1920,1080)]:
            page.set_viewport_size({'width':width,'height':height});page.wait_for_timeout(50)
            check(f'no overflow {route} {width}',page.evaluate('document.documentElement.scrollWidth<=innerWidth'))
    page.set_viewport_size({'width':390,'height':844});page.goto(BASE,wait_until='networkidle');page.wait_for_timeout(600)
    check('mobile has no pinned reel',not page.locator('#work').evaluate('(e)=>e.classList.contains("reel-ready")'))
    check('mobile skips WebGL',page.locator('.knot-host canvas').count()==0)
    page.locator('.menu-toggle').click();check('mobile menu focuses first link',page.locator('#mobile-nav a').first.evaluate('(e)=>e===document.activeElement'))
    page.keyboard.press('Escape');check('Escape returns focus',page.locator('.menu-toggle').evaluate('(e)=>e===document.activeElement'))
    shot(page,'mobile')
    touch=browser.new_context(viewport={'width':390,'height':844},has_touch=True,is_mobile=True)
    touchpage=touch.new_page();touchpage.goto(BASE,wait_until='networkidle');touchpage.locator('[data-memory="meeting"]').tap();check('touch demo works',touchpage.locator('[data-memory="meeting"]').get_attribute('aria-pressed')=='true')
    touchpage.set_viewport_size({'width':1024,'height':900});touchpage.goto(BASE,wait_until='networkidle');check('wide touch device has no pinned scene',touchpage.locator('.signature-stage').evaluate('(e)=>getComputedStyle(e).position')!='sticky' and touchpage.locator('.knot-host canvas').count()==0);touch.close()
    page.set_viewport_size({'width':1440,'height':1000});page.emulate_media(reduced_motion='reduce');page.goto(BASE,wait_until='networkidle')
    check('reduced motion no canvas',page.locator('.knot-host canvas').count()==0)
    check('reduced motion no pinned scenes',page.locator('.signature-stage').evaluate('(e)=>getComputedStyle(e).position')!='sticky' and not page.locator('#work').evaluate('(e)=>e.classList.contains("reel-ready")'))
    page.locator('[data-advance]').fill('70');page.wait_for_timeout(350);check('reduced motion keeps demos functional',page.locator('[data-cash-reserve]').inner_text()=='$0')
    nojs=browser.new_context(java_script_enabled=False,viewport={'width':390,'height':844});static=nojs.new_page();static.goto(BASE,wait_until='networkidle')
    check('no-JS graph and navigation remain',static.locator('.knot-fallback').is_visible() and static.locator('.desktop-nav').is_visible())
    check('no-JS illustration disclosure',static.locator('.demo-noscript').count()==4)
    check('no-JS controls are honestly disabled',static.locator('[data-compare]').is_disabled() and static.locator('[data-memory="meeting"]').is_disabled())
    nojs.close()
    fallback=browser.new_context(viewport={'width':1440,'height':1000});fallback.add_init_script("const old=HTMLCanvasElement.prototype.getContext;HTMLCanvasElement.prototype.getContext=function(t,...a){return /webgl/.test(t)?null:old.call(this,t,...a)}")
    f=fallback.new_page();f.goto(BASE,wait_until='networkidle');instant(f,'#untangle');f.wait_for_timeout(600)
    check('WebGL failure keeps labeled fallback',f.locator('.knot-fallback').is_visible() and f.locator('.graph-project').count()==4)
    check('WebGL failure has no dead pause control',f.locator('.signature-pause').is_disabled())
    fallback.close()
    pdf=ctx.request.get(BASE+'/assets/ratnadeep-patil-resume.pdf');check('unchanged PDF',hashlib.sha256(pdf.body()).hexdigest()=='b2862911b8b87b38c4f3dceac79ed4d913f299d4cc4901e32107bab895daf524')
    page.emulate_media(reduced_motion='no-preference');page.set_viewport_size({'width':1440,'height':1000});page.goto(BASE,wait_until='networkidle')
    page.locator('[data-project-link="synora"]').click();page.wait_for_timeout(850);page.locator('#project-synora .project-actions a').first.click();page.wait_for_load_state('networkidle')
    check('case-study navigation and transition',page.locator('h1').inner_text()=='Synora')
    page.keyboard.press('Control+k');check('case-study quick navigation opens',page.locator('.command-dialog').evaluate('(e)=>e.open'))
    check('case-study quick links return home',page.locator('.command-dialog nav a').first.get_attribute('href')=='../../index.html#work');page.keyboard.press('Escape')
    page.go_back(wait_until='networkidle');page.locator('[data-memory="meeting"]').click();check('demo works after browser Back',page.locator('[data-memory="meeting"]').get_attribute('aria-pressed')=='true')
    check('no runtime errors',not report['errors']);check('no HTTP failures',not report['http_failures'])
    browser.close()
(ROOT/'docs/design-results.json').write_text(json.dumps(report,indent=2),encoding='utf-8')
print(json.dumps({'passed':len(report['checks']),'failures':report['failures'],'errors':report['errors'],'http_failures':report['http_failures']}))
if report['failures'] or report['errors'] or report['http_failures']:raise SystemExit(1)
